    protected static function loadSupplementalDataset(string $cityName, string $entity): array
    {
        $citySlug = strtolower(str_replace(' ', '-', trim($cityName)));
        $path = storage_path("app/scraper/{$citySlug}/{$entity}.json");

        if (!is_file($path)) {
            return [];
        }

        $raw = @file_get_contents($path);
        if ($raw === false || trim($raw) === '') {
            return [];
        }

        $decoded = json_decode($raw, true);
        return is_array($decoded) ? $decoded : [];
    }

    protected static function scrapeLiveDoctors(string $cityName, ?string $cacheKey = null): array
    {
        $citySlug = strtolower(str_replace(' ', '-', trim($cityName)));
        $doctorSources = [
            ['dept' => 'General Physician', 'url' => "https://www.practo.com/{$citySlug}/doctors?specialization=General+Physician"],
            ['dept' => 'Cardiologist', 'url' => "https://www.practo.com/{$citySlug}/cardiologist"],
            ['dept' => 'Dermatologist', 'url' => "https://www.practo.com/{$citySlug}/dermatologist"],
            ['dept' => 'Orthopedist', 'url' => "https://www.practo.com/{$citySlug}/orthopedist"],
            ['dept' => 'Gynecologist/Obstetrician', 'url' => "https://www.practo.com/{$citySlug}/gynecologist-obstetrician"],
            ['dept' => 'Pediatrician', 'url' => "https://www.practo.com/{$citySlug}/pediatrician"],
            ['dept' => 'Neurologist', 'url' => "https://www.practo.com/{$citySlug}/neurologist"],
            ['dept' => 'ENT Specialist', 'url' => "https://www.practo.com/{$citySlug}/ear-nose-throat-ent-specialist"],
            ['dept' => 'Oncologist', 'url' => "https://www.practo.com/{$citySlug}/oncologist"],
            ['dept' => 'Pulmonologist', 'url' => "https://www.practo.com/{$citySlug}/pulmonologist"],
        ];

        $allDoctors = [];
        $total = count($doctorSources);

        foreach ($doctorSources as $index => $source) {
            try {
                if ($cacheKey) {
                    Cache::put($cacheKey, [
                        'status' => 'running',
                        'city' => $cityName,
                        'progress' => 30 + (int) floor((($index + 1) / max(1, $total)) * 20),
                        'message' => 'Fetching live doctors: ' . $source['dept'] . ' (' . ($index + 1) . '/' . $total . ')...',
                    ], 300);
                }

                foreach (self::buildPaginatedUrls($source['url'], 6) as $pageUrl) {
                    $response = Http::withoutVerifying()
                        ->withHeaders([
                            'User-Agent' => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36',
                            'Accept-Language' => 'en-IN,en;q=0.9',
                        ])
                        ->timeout(15)
                        ->get($pageUrl);

                    if (!$response->successful()) {
                        continue;
                    }

                    $parsed = self::parseDoctorHtml($response->body(), $cityName, $source['dept']);
                    if (empty($parsed)) {
                        continue;
                    }

                    foreach ($parsed as $doc) {
                        $doc['source_name'] = $doc['source_name'] ?? 'Practo Live Directory';
                        $doc['source_url'] = $doc['source_url'] ?? $pageUrl;
                        $allDoctors[] = $doc;
                    }
                }
            } catch (\Throwable $e) {
                Log::warning("Live doctor source failed for {$cityName} ({$source['dept']}): " . $e->getMessage());
            }
        }

        return $allDoctors;
    }

    protected static function scrapeLiveHospitals(string $cityName, ?string $cacheKey = null): array
    {
        $citySlug = strtolower(str_replace(' ', '-', trim($cityName)));
        $sources = [
            "https://www.practo.com/{$citySlug}/hospitals",
            "https://www.practo.com/{$citySlug}/clinics",
        ];

        $allHospitals = [];
        $total = count($sources);

        foreach ($sources as $index => $url) {
            try {
                if ($cacheKey) {
                    Cache::put($cacheKey, [
                        'status' => 'running',
                        'city' => $cityName,
                        'progress' => 25 + (int) floor((($index + 1) / max(1, $total)) * 15),
                        'message' => 'Fetching live hospitals (' . ($index + 1) . '/' . $total . ')...',
                    ], 300);
                }

                foreach (self::buildPaginatedUrls($url, 8) as $pageUrl) {
                    $response = Http::withoutVerifying()
                        ->withHeaders([
                            'User-Agent' => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36',
                            'Accept-Language' => 'en-IN,en;q=0.9',
                        ])
                        ->timeout(15)
                        ->get($pageUrl);

                    if (!$response->successful()) {
                        continue;
                    }

                    $parsed = self::parseHospitalHtml($response->body(), $cityName);
                    if (empty($parsed)) {
                        continue;
                    }

                    foreach ($parsed as $hosp) {
                        $hosp['source_name'] = $hosp['source_name'] ?? 'Practo Live Directory';
                        $hosp['source_url'] = $hosp['source_url'] ?? $pageUrl;
                        $allHospitals[] = $hosp;
                    }
                }
            } catch (\Throwable $e) {
                Log::warning("Live hospital source failed for {$cityName}: " . $e->getMessage());
            }
        }

        return $allHospitals;
    }

    protected static function buildPaginatedUrls(string $baseUrl, int $maxPages): array
    {
        $urls = [];
        for ($page = 1; $page <= $maxPages; $page++) {
            if ($page === 1) {
                $urls[] = $baseUrl;
                continue;
            }

            $separator = str_contains($baseUrl, '?') ? '&' : '?';
            $urls[] = $baseUrl . $separator . 'page=' . $page;
        }

        return array_values(array_unique($urls));
    }

