        $supplementalBloodBanks = self::loadSupplementalDataset($cityName, 'blood_banks');
        if (!empty($supplementalBloodBanks)) {
            $scrapedBloodBanks = array_merge($scrapedBloodBanks, $supplementalBloodBanks);
        }

        [$scrapedBloodBanks, $bloodBankRejected] = self::filterBloodBankRecords($scrapedBloodBanks, $cityName);
        
        foreach ($scrapedBloodBanks as $bb) {
            \App\Models\BloodBank::updateOrCreate(
                ['name_en' => $bb['name_en'], 'city' => $bb['city']],
                $bb
            );
        }

        if ($cacheKey) {
            \Illuminate\Support\Facades\Cache::put($cacheKey, ['status' => 'completed', 'city' => $cityName, 'progress' => 100, 'message' => "Blood bank scraping completed for {$cityName}."], 300);
        }

        return $scrapedBloodBanks;
    }

