                'is_verified' => true,
            ]
        ];

        $liveHospitals = [];
        if (!$forceFallback) {
            $liveHospitals = self::scrapeLiveHospitals($cityName, $cacheKey);
        }
        $supplementalHospitals = self::loadSupplementalDataset($cityName, 'hospitals');
        $allHospitals = array_merge($detailedHospitals, $liveHospitals, $supplementalHospitals);
        
        $unique = [];
        foreach ($allHospitals as $h) {
            $h = self::normalizeHospitalDetailRow($h, $cityName);
            $unique[strtolower(trim($h['name_en']))] = $h;
        }
        $allHospitals = array_values($unique);

        [$allHospitals, $rejected] = self::filterHospitalRecords($allHospitals, $cityName);
        
        if (!empty($allHospitals)) {
            \App\Services\HealthcareSyncService::syncBatch([], $allHospitals, $cacheKey, 100, $cityName);
        } else if ($cacheKey) {
            \Illuminate\Support\Facades\Cache::put($cacheKey, ['status' => 'completed', 'city' => $cityName, 'progress' => 100, 'message' => "Hospital scraping completed for {$cityName}."], 300);
        }

        return $allHospitals;
    }

