            $liveDoctors = self::scrapeLiveDoctors($cityName, $cacheKey);
        }
        $supplementalDoctors = self::loadSupplementalDataset($cityName, 'doctors');
        $allDoctors = array_merge($detailedDoctors, $liveDoctors, $supplementalDoctors);
        
        $unique = [];
        foreach ($allDoctors as $d) {
            $key = !empty($d['registration_number']) ? strtolower(trim($d['registration_number'])) : strtolower(trim($d['first_name'] . ' ' . $d['last_name']));
            $unique[$key] = $d;
        }
        $allDoctors = array_values($unique);

        [$allDoctors, $rejected] = self::filterDoctorRecords($allDoctors, $cityName);
        
        if (!empty($allDoctors)) {
            \App\Services\HealthcareSyncService::syncBatch($allDoctors, [], $cacheKey, 100, $cityName);
        } else if ($cacheKey) {
            \Illuminate\Support\Facades\Cache::put($cacheKey, ['status' => 'completed', 'city' => $cityName, 'progress' => 100, 'message' => "Doctor scraping completed for {$cityName}."], 300);
        }

        return $allDoctors;
